{
  "scope_issues": [
    "The policy does not specify whether a donation grouped with CAF card or voucher redemptions in a batch constitutes a separate donation for Gift Aid purposes, though it notes the batch was made on a different date."
  ],
  "statuses": [
    {
      "evidence_quote": "I run a small, independent charity which attempts to help people struggling with their vet costs. I have several people who pay monthly by direct debit and also receive some one off donations.",
      "id": "a1",
      "justification": "The customer describes receiving donations from individuals, satisfying the condition that the donor is an individual who donates to a charity or CASC.",
      "status": "TRUE"
    },
    {
      "evidence_quote": "Her tax summary for the year to 5 April 2026 shows £980 of Income Tax paid. Her signed note lists £200 of other Gift Aid donations that year; the treasurer’s sheet shows £30 recoverable on this £120 and £50 on the others, £80 in total, well below her £980.",
      "id": "a2",
      "justification": "Elaine’s tax summary shows she paid £980 in Income Tax, which is greater than the total Gift Aid recoverable (£80), meaning she has paid at least as much as the claimed Gift Aid amount.",
      "status": "TRUE"
    },
    {
      "evidence_quote": "Elaine signed an electronic Gift Aid declaration on 15 March, and the e-signature service holds the signed document, timestamp and audit record. The declaration says it covers this donation, and the finance assistant matched it to FP-0316-EL through her donor record.",
      "id": "a3",
      "justification": "The Gift Aid declaration is explicitly stated to cover this donation and is verified by timestamp and audit records, confirming permission to claim Gift Aid.",
      "status": "TRUE"
    },
    {
      "evidence_quote": "It did not go through a payroll giving scheme, and no shares, securities or other assets were delivered.",
      "id": "a4",
      "justification": "The donation was made via direct debit from Elaine’s personal account, not through Payroll Giving, satisfying the condition that it is not made through Payroll Giving.",
      "status": "TRUE"
    },
    {
      "evidence_quote": "The sales, booking and event records show nothing linked to this payment, and the only thing sent to Elaine was the standard thank-you email; she was not offered admission, advertising, a product or any other benefit.",
      "id": "a5",
      "justification": "No goods or services were purchased or offered in exchange, and no benefit was provided beyond a standard thank-you email, satisfying that the donation is not a payment for goods or services.",
      "status": "TRUE"
    },
    {
      "evidence_quote": "she was not offered admission, advertising, a product or any other benefit",
      "id": "a6",
      "justification": "The donation was not associated with any benefit, such as admission or advertising, and no benefit over a certain limit was given, so the condition of a 'benefit' over a limit does not apply.",
      "status": "TRUE"
    },
    {
      "evidence_quote": "no shares, securities or other assets were delivered",
      "id": "a7",
      "justification": "The donation did not involve shares or any form of securities, satisfying the condition that it is not of shares or any other form of securities.",
      "status": "TRUE"
    },
    {
      "evidence_quote": "An older spreadsheet groups it with two CAF card and voucher redemptions (CC-0314, VC-0317), but those were paid to the charity in a combined batch on 18 March, while FP-0316-EL came directly from Elaine’s bank on 16 March.",
      "id": "a8",
      "justification": "The donation came directly from Elaine, not from a CAF card or voucher, and the CAF redemptions were made on a different date and in a separate batch, so this donation is not from a charity card or voucher.",
      "status": "TRUE"
    },
    {
      "evidence_quote": "the charity’s 2023 HMRC recognition letter is on file, and the treasurer’s status check confirms the charity was still recognised on 16 March 2026.",
      "id": "a9",
      "justification": "The charity’s recognition by HMRC is confirmed for the date of the donation, satisfying the condition that it is recognised as a charity or CASC for tax purposes.",
      "status": "TRUE"
    }
  ]
}
